 c.saveState();c.setFont('Times-Roman',10);c.setFillColor(colors.HexColor('#47545e'));c.drawString(M,M+3,'Team Vector | GHSL final project report');c.drawRightString(W-M,M+3,f'{doc.page}');c.restoreState()
